		char *p = malloc (strlen (msg) + strlen (*s) + 1);
		if (p) {
			strcpy (p, *s);
			free (*s);
			*s = p;
			strcpy (p + strlen (p), msg);
		}
	} else {
		*s = strdup (msg);
	}
}

static void __errorFunc(void *opaque, const char *msg) {
	__appendString (msg, opaque);
	char **p = (char **)opaque;
	if (R_STR_ISNOTEMPTY (p)) {
		int n = strlen (*p);
		char *ptr = malloc (n + 2);
		if (ptr) {
			strcpy (ptr, *p);
			ptr[n] = '\n';
			ptr[n + 1] = 0;
