/* parse C code and return it in key-value form */

static bool __typeLoad(void *p, const char *k, const char *v) {
	if (!p) {
		return false;
	}
	int btype = 0;
	LoadContext *loader = (LoadContext *)p;
	RAnal *anal = loader->anal;
